import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS, en, DUR, Camara, Textura, Profundidad, Brillo, Paso, tono, Chip, Etiqueta, Contador, Ondas, Destello, golpe, Easing, interpolate, clamp, h, enCamino, seguir, FONT, MANO} from './kit';

// ---------- utilidades ----------
const cl = (v: number, a = 0, b = 1) => Math.max(a, Math.min(b, v));
const eo = (x: number) => 1 - Math.pow(1 - cl(x), 3);
const eio = (x: number) => { const k = cl(x); return k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2; };
const ro = (s: number, a: number, b: number) => cl((s - a) / (b - a));
const pul = (s: number, t: number, d = 3) => (s < t ? 0 : Math.exp(-(s - t) * d));
const GOLD = '#FFC83D';
const DULL = '#B79A52';
const GOLD3 = '#F2CE6B';
const GRAY = '#8d8f96';
const RED = '#FF4D4D';
const RIM = 'rgba(90,55,0,0.6)';
const PIEL = ['#e8b98e', '#c98a5b', '#8d5a3a', '#5a3a28', '#d9a577', '#a86d44'];
const MANGA = ['#2f6f8f', '#9c3b3b', '#d8c9a0', '#3b7a4b', '#6b4a9c', '#caa04a'];
const fix = (l: {t: number; s: string}[]) => {
  const o: {t: number; s: string}[] = [];
  let last = -9;
  [...l].sort((a, b) => a.t - b.t).forEach((e) => { if (e.t - last >= 0.27) { o.push(e); last = e.t; } });
  return o;
};
const starPts = (r: number) => `0,${-r} ${r * 0.28},${-r * 0.28} ${r},0 ${r * 0.28},${r * 0.28} 0,${r} ${-r * 0.28},${r * 0.28} ${-r},0 ${-r * 0.28},${-r * 0.28}`;

// ---------- tiempos (todo atado a palabras del guion) ----------
// E1
const T_PERDIO = en('perdió');
// E2
const T_ANO = en('Año'), T_MIL = en('trescientos'), T_MANSA = en('Mansa'), T_MALI = en('Malí'), T_SALE = en('sale'), T_VIAJE = en('viaje'), T_MECA = en('Meca');
// E3
const T_LO = en('Lo'), T_ACOMP = en('acompañan'), T_CAMELLOS = en('camellos'), T_ORO3 = en('oro', 3), T_RICOS = en('ricos');
// E4
const T_AL = en('Al'), T_CAIRO = en('Cairo'), T_REPARTE = en('reparte'), T_MANOS = en('manos'), T_LLENAS = en('llenas');
const T_REGALOS = en('Regalos'), T_LIMOSNAS = en('limosnas'), T_COMPRAS = en('compras'), T_REGATEAR = en('regatear');
// E5
const T_Y2 = en('Y', 2), T_QUE = en('qué'), T_CALLE = en('calle'), T_ESPECIAL = en('especial'), T_PRECIO = en('precio'), T_CAYO = en('cayó');
// E6
const T_UN = en('Un'), T_CRONISTA = en('cronista'), T_DOCE = en('doce'), T_DESPUES = en('después'), T_SEGUIA = en('seguía'), T_EGIPTO = en('Egipto');
// E7
const T_DICEN = en('Dicen'), T_PEDIR = en('pedir'), T_PRESTADO = en('prestado'), T_PAGAR = en('pagar'), T_INTERESES = en('intereses');
// E8
const T_Y3 = en('Y', 3), T_LECCION = en('lección'), T_SOBRA = en('sobra'), T_VALE = en('vale'), T_PASA = en('Pasa'), T_ORO7 = en('oro', 7), T_DINERO1 = en('dinero', 1), T_SEIMPRIME = en('imprime');
// E9
const T_DALE = en('Dale'), T_LIKE = en('like'), T_ORO8 = en('oro', 8), T_ENVIASELO = en('envíaselo');

// Color de la moneda protagonista: intenso, apagado en El Cairo, rojo en la caída, gris, y sereno al final.
const heroCol = (s: number) => tono(s, [0, T_REPARTE, T_REGATEAR, T_CAYO - 0.1, T_CAYO + 0.3, T_UN + 1.0, T_ORO7 - 0.5, T_ORO7 + 0.2], [GOLD, GOLD, DULL, DULL, RED, GRAY, GRAY, GOLD3]);

// ---------- piezas dibujadas ----------
const Moneda: React.FC<{x: number; y: number; r: number; c: string; sx?: number; rot?: number; op?: number}> = ({x, y, r, c, sx = 1, rot = 0, op = 1}) => (
  <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${Math.max(0.12, Math.abs(sx))} 1)`} opacity={op}>
    <circle r={r} fill={c} stroke={RIM} strokeWidth={Math.max(2, r * 0.07)} />
    <circle r={r * 0.74} fill="none" stroke={RIM} strokeWidth={Math.max(1.5, r * 0.05)} opacity={0.6} />
    <polygon points={starPts(r * 0.4)} fill="rgba(90,55,0,0.4)" />
    <path d={`M ${-r * 0.68} ${-r * 0.2} A ${r * 0.72} ${r * 0.72} 0 0 1 ${r * 0.05} ${-r * 0.7}`} stroke="rgba(255,255,255,0.55)" strokeWidth={Math.max(2, r * 0.09)} fill="none" strokeLinecap="round" />
  </g>
);

const MonedaPlana: React.FC<{x: number; y: number; c: string; w?: number}> = ({x, y, c, w = 36}) => (
  <g transform={`translate(${x} ${y})`}>
    <ellipse cx={0} cy={6} rx={w} ry={w * 0.34} fill="rgba(80,50,0,0.85)" />
    <ellipse cx={0} cy={0} rx={w} ry={w * 0.34} fill={c} stroke={RIM} strokeWidth={2.5} />
    <ellipse cx={-w * 0.2} cy={-w * 0.06} rx={w * 0.45} ry={w * 0.1} fill="rgba(255,255,255,0.35)" />
  </g>
);

const Billete: React.FC<{x: number; y: number; r?: number; k?: number; op?: number}> = ({x, y, r = 0, k = 1, op = 1}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`} opacity={op}>
    <rect x={-150} y={-70} width={300} height={140} rx={14} fill="#b4d9a2" stroke="#3f6b3a" strokeWidth={5} />
    <rect x={-134} y={-54} width={268} height={108} rx={9} fill="none" stroke="#3f6b3a" strokeWidth={2.5} opacity={0.65} />
    <circle r={42} fill="rgba(255,255,255,0.35)" stroke="#3f6b3a" strokeWidth={3} />
    <text y={15} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={46} fill="#2f5a2b">$</text>
    <path d="M -150 -70 L 24 -70 L -56 70 L -150 70 Z" fill="rgba(255,255,255,0.16)" />
  </g>
);

const Gente: React.FC<{x: number; y: number; k: number; i: number}> = ({x, y, k, i}) => {
  const {s} = useS();
  const bob = Math.abs(Math.sin(s * 5 + i * 1.7)) * 7;
  const rob = ['#e8dcc0', '#b5472f', '#2f6f8f', '#d9a441', '#6b4a9c', '#3b7a4b'][i % 6];
  const piel = ['#5a3a28', '#7a4c30', '#8d5a3a', '#a86d44'][i % 4];
  return (
    <g transform={`translate(${x} ${y - bob}) scale(${k})`}>
      <ellipse cx={0} cy={bob} rx={34} ry={8} fill="rgba(0,0,0,0.3)" />
      <path d="M -30 0 L -22 -110 Q 0 -128 22 -110 L 30 0 Z" fill={rob} stroke="rgba(0,0,0,0.3)" strokeWidth={3} />
      <circle cx={0} cy={-142} r={22} fill={piel} />
      <path d="M -25 -146 Q 0 -178 25 -146 Q 0 -156 -25 -146 Z" fill={i % 2 ? '#f1e6c8' : '#c9482b'} />
      <circle cx={8} cy={-142} r={2.8} fill="#1b0f08" />
      <circle cx={8.9} cy={-143} r={1} fill="#fff" />
    </g>
  );
};

const Camello: React.FC<{x: number; y: number; i: number; brillo: number}> = ({x, y, i, brillo}) => {
  const {s} = useS();
  const ph = s * 5 + i * 0.9;
  const body = ['#c79a62', '#b98a52', '#d1a672'][i % 3];
  const dark = '#8a5f33';
  const bob = Math.sin(ph * 2) * 4;
  const leg = (lx: number, k: number, key: number) => (
    <g key={key} transform={`translate(${lx} -150) rotate(${Math.sin(ph + k) * 16})`}>
      <rect x={-12} y={0} width={24} height={150} rx={11} fill={body} stroke={dark} strokeWidth={3} />
      <rect x={-14} y={134} width={28} height={16} rx={7} fill={dark} />
    </g>
  );
  return (
    <g transform={`translate(${x} ${y})`}>
      <ellipse cx={0} cy={0} rx={190} ry={16} fill="rgba(0,0,0,0.28)" />
      {leg(-100, 0, 0)}{leg(-60, Math.PI, 1)}{leg(80, Math.PI, 2)}{leg(115, 0, 3)}
      <g transform={`translate(0 ${bob})`}>
        <path d="M 110 -230 Q 190 -250 190 -350" stroke={dark} strokeWidth={56} fill="none" strokeLinecap="round" />
        <path d="M 110 -230 Q 190 -250 190 -350" stroke={body} strokeWidth={46} fill="none" strokeLinecap="round" />
        <path d="M -150 -215 Q -160 -150 -90 -140 L 100 -140 Q 150 -150 140 -215 Q 120 -290 -20 -285 Q -140 -280 -150 -215 Z" fill={body} stroke={dark} strokeWidth={4} />
        <ellipse cx={-20} cy={-305} rx={56} ry={54} fill={body} stroke={dark} strokeWidth={4} />
        <ellipse cx={212} cy={-362} rx={46} ry={28} transform="rotate(18 212 -362)" fill={body} stroke={dark} strokeWidth={4} />
        <circle cx={224} cy={-372} r={5} fill="#1b0f08" />
        <circle cx={225.5} cy={-373.5} r={1.7} fill="#fff" />
        <path d="M -75 -290 L 55 -290 L 78 -185 L -98 -185 Z" fill={['#b5472f', '#2f6f8f', '#6b4a9c'][i % 3]} stroke="rgba(0,0,0,0.3)" strokeWidth={3} />
        <path d="M -75 -270 L 66 -270" stroke={GOLD} strokeWidth={8} />
        <circle cx={-70} cy={-250} r={78 + 30 * brillo} fill={`rgba(255,200,61,${0.2 + 0.35 * brillo})`} />
        {[-70, 62].map((sx, k) => (
          <g key={k} transform={`translate(${sx} ${k ? -232 : -248})`}>
            <ellipse cx={0} cy={0} rx={48} ry={60} fill="#9b7544" stroke="#4a3216" strokeWidth={4} />
            <path d="M -30 -50 Q 0 -78 30 -50" fill="#6f522c" stroke="#4a3216" strokeWidth={3} />
            <ellipse cx={0} cy={-62} rx={24} ry={10} fill={GOLD} stroke={RIM} strokeWidth={3} />
            <polygon points={starPts(10 + 16 * brillo)} transform="translate(14 -66)" fill="#fff" opacity={0.6 + 0.4 * brillo} />
          </g>
        ))}
        <circle cx={150} cy={-262 + Math.sin(ph * 2 + 1) * 6} r={9} fill={GOLD} stroke={RIM} strokeWidth={2} />
        <path d="M -150 -200 Q -178 -170 -170 -120" stroke={dark} strokeWidth={9} fill="none" strokeLinecap="round" />
      </g>
    </g>
  );
};

const Rey: React.FC<{x: number; y: number; k: number}> = ({x, y, k}) => {
  const {s} = useS();
  const ph = s * 9;
  const bob = Math.sin(ph * 2) * 5;
  const leg = (lx: number, kk: number, key: number) => (
    <g key={key} transform={`translate(${lx} -90) rotate(${Math.sin(ph + kk) * 20})`}>
      <rect x={-10} y={0} width={20} height={92} rx={9} fill="#6a3f22" stroke="#3b2210" strokeWidth={3} />
      <rect x={-12} y={78} width={24} height={14} rx={6} fill="#2a170a" />
    </g>
  );
  return (
    <g transform={`translate(${x} ${y}) scale(${k})`}>
      <ellipse cx={0} cy={0} rx={140} ry={12} fill="rgba(0,0,0,0.3)" />
      {leg(-85, 0, 0)}{leg(-50, Math.PI, 1)}{leg(60, Math.PI, 2)}{leg(95, 0, 3)}
      <g transform={`translate(0 ${bob})`}>
        <path d="M -110 -130 Q -150 -110 -140 -60 Q -125 -90 -105 -100 Z" fill="#2a170a" />
        <path d="M 70 -170 Q 130 -190 150 -260" stroke="#3b2210" strokeWidth={50} fill="none" strokeLinecap="round" />
        <path d="M 70 -170 Q 130 -190 150 -260" stroke="#7a4a2a" strokeWidth={40} fill="none" strokeLinecap="round" />
        <ellipse cx={-5} cy={-130} rx={112} ry={58} fill="#7a4a2a" stroke="#3b2210" strokeWidth={4} />
        <ellipse cx={172} cy={-270} rx={42} ry={24} transform="rotate(30 172 -270)" fill="#7a4a2a" stroke="#3b2210" strokeWidth={4} />
        <circle cx={182} cy={-276} r={4.5} fill="#1b0f08" />
        <circle cx={183.4} cy={-277.4} r={1.5} fill="#fff" />
        <path d="M 150 -300 L 160 -330 L 172 -298 Z" fill="#3b2210" />
        <path d="M 120 -300 Q 90 -250 80 -190" stroke="#2a170a" strokeWidth={14} fill="none" strokeLinecap="round" />
        <rect x={-70} y={-196} width={120} height={70} rx={14} fill={GOLD} stroke={RIM} strokeWidth={4} />
        <path d="M -70 -176 L 50 -176" stroke="#b5472f" strokeWidth={7} />
        <path d="M -40 -190 Q -118 -230 -122 -160 Q -80 -190 -40 -170 Z" fill="#f1e6c8" opacity={0.9 + 0.1 * Math.sin(ph)} stroke="rgba(0,0,0,0.25)" strokeWidth={3} />
        <path d="M -16 -190 Q -2 -290 22 -318 L 60 -318 Q 66 -260 50 -190 Z" fill="#ffd25e" stroke={RIM} strokeWidth={4} />
        <path d="M 8 -230 Q 30 -250 50 -230" stroke="#b5472f" strokeWidth={6} fill="none" />
        <circle cx={38} cy={-342} r={32} fill="#4a2f20" stroke="#25140a" strokeWidth={3} />
        <path d="M 66 -346 L 80 -336 L 66 -328 Z" fill="#4a2f20" />
        <circle cx={54} cy={-346} r={4.8} fill="#1b0f08" />
        <circle cx={55.5} cy={-347.5} r={1.7} fill="#fff" />
        <ellipse cx={34} cy={-374} rx={46} ry={28} fill="#f1e6c8" stroke="rgba(0,0,0,0.25)" strokeWidth={3} />
        <path d="M -8 -376 Q 34 -350 76 -376" stroke="rgba(120,90,50,0.6)" strokeWidth={4} fill="none" />
        <path d="M -2 -392 Q 34 -370 70 -392" stroke="rgba(120,90,50,0.45)" strokeWidth={4} fill="none" />
        <circle cx={34} cy={-402} r={9} fill={GOLD} stroke={RIM} strokeWidth={2} />
        <g transform="translate(-120 -118)">
          <ellipse cx={0} cy={0} rx={30} ry={38} fill="#9b7544" stroke="#4a3216" strokeWidth={3} />
          <ellipse cx={0} cy={-38} rx={18} ry={7} fill={GOLD} stroke={RIM} strokeWidth={2} />
        </g>
      </g>
    </g>
  );
};

const Palma: React.FC<{x: number; y: number; r?: number; k?: number; piel: string; manga: string; pila?: number; c?: string; bob?: number}> = ({x, y, r = 0, k = 1, piel, manga, pila = 0, c = GOLD, bob = 0}) => {
  const dk = 'rgba(60,30,10,0.45)';
  return (
    <g transform={`translate(${x} ${y + bob}) rotate(${r}) scale(${k})`}>
      <rect x={-52} y={20} width={104} height={900} rx={40} fill={piel} stroke={dk} strokeWidth={4} />
      <rect x={-68} y={214} width={136} height={800} rx={30} fill={manga} stroke="rgba(0,0,0,0.35)" strokeWidth={4} />
      <rect x={-68} y={214} width={136} height={26} fill="rgba(255,255,255,0.2)" />
      <ellipse cx={0} cy={-6} rx={76} ry={68} fill={piel} stroke={dk} strokeWidth={4} />
      {[[-56, -60, -14, 70], [-20, -72, -4, 86], [18, -72, 5, 80], [54, -58, 15, 62]].map(([fx, fy, a, len], i) => (
        <g key={i} transform={`translate(${fx} ${fy}) rotate(${a})`}><rect x={-15} y={-len} width={30} height={len + 18} rx={15} fill={piel} stroke={dk} strokeWidth={3} /></g>
      ))}
      <g transform="translate(-68 -4) rotate(-62)"><rect x={-16} y={-70} width={32} height={90} rx={16} fill={piel} stroke={dk} strokeWidth={3} /></g>
      <ellipse cx={-8} cy={-4} rx={40} ry={26} fill="rgba(255,255,255,0.14)" />
      {Array.from({length: Math.max(0, Math.min(8, Math.round(pila)))}).map((_, j) => <MonedaPlana key={j} x={0} y={-4 - j * 8} c={c} w={36} />)}
    </g>
  );
};

const Saco: React.FC<{x: number; y: number; k?: number}> = ({x, y, k = 1}) => (
  <g transform={`translate(${x} ${y}) scale(${k})`}>
    <ellipse cx={0} cy={112} rx={118} ry={18} fill="rgba(0,0,0,0.35)" />
    <path d="M -100 100 Q -130 -10 -50 -60 L 50 -60 Q 130 -10 100 100 Q 0 130 -100 100 Z" fill="#8a6a3c" stroke="#4a3216" strokeWidth={5} />
    <path d="M -52 -60 Q 0 -100 52 -60 Q 0 -78 -52 -60 Z" fill="#6f522c" stroke="#4a3216" strokeWidth={4} />
    <path d="M -58 -58 Q 0 -40 58 -58" stroke="#d9a441" strokeWidth={10} fill="none" strokeLinecap="round" />
    <path d="M -80 20 Q -60 -20 -30 -30" stroke="rgba(255,255,255,0.2)" strokeWidth={10} fill="none" strokeLinecap="round" />
  </g>
);

// ================= SITIO 1 y 9: el mercado con lluvia de oro (E1 y el bucle E9) =================
const RAIN = Array.from({length: 40}).map((_, i) => ({
  x: h(i * 3 + 1) * 1180 - 50,
  r: 14 + h(i * 7) * 26,
  k: 3 + Math.floor(h(i * 5) * 7),
  y0: h(i * 11) * 2400 - 300,
  w: 2 + Math.floor(h(i * 13) * 3),
  big: i % 9 === 0,
}));

const Mercado: React.FC<{cierre?: boolean}> = ({cierre = false}) => {
  const {s} = useS();
  const ph = (2 * Math.PI * s) / DUR;
  const col = cierre ? tono(s, [T_DALE, DUR - 1.2], [GOLD3, GOLD], 0.8) : tono(s, [0, T_PERDIO], [GOLD, GRAY], 0.4);
  const hy = cierre ? 700 + 190 * (s - DUR) : 700 + 190 * s;
  const hx = 540 + 40 * Math.sin(ph * 15);
  const sx = 0.55 + 0.45 * Math.cos(ph * 22);
  const pg = cierre ? 0 : golpe(s, T_PERDIO, 18, 7);
  const cam = cierre ? [{t: T_DALE, x: 540, y: 1000, zoom: 1.15}, {t: DUR, x: 540, y: 700, zoom: 1.0}] : [{t: 0, x: 540, y: 700, zoom: 1.0}, {t: T_ANO, x: 540, y: 1000, zoom: 1.12}];
  const toldos = [['#b5472f', '#f1e6c8'], ['#2f6f8f', '#f1e6c8'], ['#d9a441', '#8a3b2a'], ['#3b7a4b', '#f1e6c8'], ['#6b4a9c', '#f1e6c8']];
  return (
    <AbsoluteFill>
      <Textura tipo="piel" base="linear-gradient(180deg,#2b1a0e 0%,#6b4524 52%,#2a190c 100%)" linea="rgba(255,196,110,0.30)" luz="rgba(255,190,90,0.20)" semilla={3} />
      <Camara paradas={cam}>
        <Brillo x={540} y={1000} r={720} color="rgba(255,200,61,0.26)" />
        <svg width={1080} height={1920} style={{position: 'absolute', inset: 0, overflow: 'visible'}}>
          {[170, 900].map((mx, i) => (
            <g key={i} fill="rgba(36,20,9,0.6)">
              <rect x={mx - 22} y={520} width={44} height={470} />
              <ellipse cx={mx} cy={520} rx={36} ry={52} />
              <rect x={mx - 4} y={440} width={8} height={70} />
              <rect x={mx - 40} y={640} width={80} height={14} />
            </g>
          ))}
          {toldos.map((cs, i) => {
            const x = i * 250 - 60;
            return (
              <g key={i}>
                <rect x={x + 18} y={1010} width={16} height={200} fill="#3a2412" />
                <rect x={x + 206} y={1010} width={16} height={200} fill="#3a2412" />
                {[0, 1, 2, 3, 4].map((j) => <polygon key={j} points={`${x + j * 48},1000 ${x + j * 48 + 48},1000 ${x + j * 48 + 56},1066 ${x + j * 48 + 8},1066`} fill={j % 2 ? cs[1] : cs[0]} stroke="rgba(0,0,0,0.25)" strokeWidth={2} />)}
                <rect x={x} y={1190} width={244} height={26} fill="#5a3a1c" stroke="#2c180a" strokeWidth={4} />
                {[0, 1, 2].map((j) => <circle key={j} cx={x + 50 + j * 70} cy={1166} r={22} fill={['#c9482b', '#d9a441', '#4a7a4b'][(i + j) % 3]} stroke="rgba(0,0,0,0.3)" strokeWidth={3} />)}
              </g>
            );
          })}
          {RAIN.map((c, i) => {
            const speed = (2400 * c.k) / DUR;
            const y = ((c.y0 + s * speed) % 2400 + 2400) % 2400 - 300;
            const x = c.x + Math.sin(ph * c.w * 3 + i) * 18;
            return <Moneda key={i} x={x} y={y} r={c.big ? c.r * 1.7 : c.r} c={GOLD} sx={Math.cos(ph * (8 + c.w * 6) + i)} rot={Math.sin(ph * 5 + i) * 25} op={c.big ? 0.9 : 1} />;
          })}
          <g transform={`translate(${hx} ${hy}) scale(${1 + 0.1 * pg})`}>
            <ellipse cx={0} cy={0} rx={190} ry={190} fill={`rgba(255,200,61,${cierre ? 0.2 : 0.18})`} />
            <Moneda x={0} y={0} r={150} c={col} sx={sx} rot={Math.sin(ph * 15) * 8} />
          </g>
        </svg>
        {!cierre && <Ondas x={hx} y={700 + 190 * T_PERDIO} t0={T_PERDIO} color="rgba(190,190,200,0.9)" radio={360} />}
        {cierre && <Ondas x={540} y={1000} t0={T_ORO8} color={GOLD} radio={520} />}
      </Camara>
    </AbsoluteFill>
  );
};

// ================= SITIO 2: el mapa y el rey (E2) =================
const PATH: [number, number][] = [[200, 1560], [300, 1400], [430, 1290], [520, 1180], [640, 1040], [760, 880], [880, 700]];
const R_T0 = T_SALE;
const R_T1 = T_MECA + 0.3;

const Mapa: React.FC = () => {
  const {s, spr} = useS();
  const q = enCamino(s, PATH, R_T0, R_T1);
