// ================= SITIO 4: el bazar de El Cairo y la moneda de mano en mano (E4) =================
const HAND: [number, number][] = [[230, 1200], [470, 1060], [700, 1230], [930, 1080], [1160, 1240], [1390, 1100]];
const TH = [T_REPARTE + 0.15, T_MANOS, T_LLENAS, T_LIMOSNAS, T_COMPRAS, T_REGATEAR];
const hopPos = (s: number) => {
  const t0 = T_AL + 0.3;
  if (s < TH[0]) {
    const p = ro(s, t0, TH[0]);
    return {x: HAND[0][0] - 60 * (1 - p), y: HAND[0][1] - 40 - 1000 * (1 - p * p)};
  }
  let i = 0;
  while (i < TH.length - 2 && s >= TH[i + 1]) i++;
  const p = cl((s - TH[i]) / (TH[i + 1] - TH[i]));
  const a = HAND[i], b = HAND[i + 1];
  return {x: a[0] + (b[0] - a[0]) * eio(p), y: a[1] - 40 + (b[1] - a[1]) * eio(p) - 200 * 4 * p * (1 - p)};
};

const Zoco: React.FC = () => {
  const {s} = useS();
  const hp = hopPos(s);
  const hot = hp.y;
  const cam = [{t: T_AL, x: 300, y: 1000, zoom: 1.0}, ...HAND.map((p, i) => ({t: TH[i], x: p[0] + 70, y: p[1] - 150, zoom: 1.3}))];
  const col = heroCol(s);
  return (
    <AbsoluteFill>
      <Textura tipo="piel" base="linear-gradient(180deg,#3a2616 0%,#8a5e30 58%,#3a2412 100%)" linea="rgba(255,205,130,0.32)" luz="rgba(255,200,110,0.26)" semilla={8} />
