              <circle cx={-65 + i * 330} cy={620 + (i % 2) * 40} r={26} fill={GOLD} />
              <line x1={-65 + i * 330} y1={520} x2={-65 + i * 330} y2={600 + (i % 2) * 40} stroke="#3a2412" strokeWidth={4} />
            </g>
          ))}
          {Array.from({length: 7}).map((_, i) => (
            <g key={'t' + i}>
              {[0, 1, 2, 3].map((j) => <polygon key={j} points={`${-210 + i * 330 + j * 74},930 ${-210 + i * 330 + j * 74 + 74},930 ${-210 + i * 330 + j * 74 + 84},1000 ${-210 + i * 330 + j * 74 + 10},1000`} fill={['#b5472f', '#f1e6c8', '#2f6f8f', '#d9a441'][(i + j) % 4]} />)}
              <rect x={-230 + i * 330} y={1360} width={300} height={34} fill="#5a3a1c" stroke="#2c180a" strokeWidth={4} />
            </g>
          ))}
          {HAND.map((p, i) => {
            const land = s >= TH[i];
            const sinceL = s - TH[i];
            const dropsIn = [0, 1].reduce((a, j) => a + (s > TH[i] + 0.2 + 0.22 * j + 0.28 ? 1 : 0), 0);
            return (
              <g key={i}>
                <Palma x={p[0]} y={p[1]} r={(i % 2 ? -1 : 1) * (6 + (i % 3) * 3)} k={1.05} piel={PIEL[i % 6]} manga={MANGA[(i * 5) % 6]} pila={(land ? 1 : 0) + dropsIn} c={i === 5 ? GOLD3 : GOLD} bob={Math.sin(s * 3 + i) * 6 + (land ? 14 * golpe(s, TH[i], 18, 8) : 0)} />
                {[0, 1].map((j) => {
                  const t = TH[i] + 0.2 + 0.22 * j;
                  const pp = ro(s, t, t + 0.28);
                  return pp > 0 && pp < 1 ? <Moneda key={j} x={p[0] + (j ? 14 : -14)} y={p[1] - 330 * (1 - pp * pp)} r={20} c={GOLD} sx={Math.cos(s * 18 + j)} /> : null;
                })}
                {sinceL > 0 && sinceL < 0.5 && <Ondas x={p[0]} y={p[1]} t0={TH[i]} color="rgba(255,236,170,0.9)" radio={160} />}
              </g>
            );
          })}
          <Brillo x={hp.x} y={hp.y} r={150} color="rgba(255,236,170,0.55)" />
          <Moneda x={hp.x} y={hot} r={42} c={col} sx={0.55 + 0.45 * Math.cos(s * 12)} />
