};

// ================= SITIO 7: el préstamo (E7) =================
const Prestamo: React.FC = () => {
  const {s} = useS();
  const ease = {...clamp, easing: Easing.inOut(Easing.cubic)};
  const sackX = interpolate(s, [T_DICEN, T_PEDIR, T_PRESTADO + 0.4], [240, 300, 540], ease);
  const sackY = interpolate(s, [T_DICEN, T_PEDIR, T_PRESTADO + 0.4], [1130, 1090, 1130], ease);
  const kingX = interpolate(s, [T_DICEN + 0.2, T_PEDIR + 0.1, T_PRESTADO + 0.4], [1350, 880, 650], ease);
  const lendX = sackX - 60;
  const y0 = 1290;
  const prog = ro(s, T_PRESTADO, T_PRESTADO + 0.7);
  const wL = {x: lendX - 42, y: y0 + 186}, wK = {x: kingX + 42, y: y0 + 186};
  const links = [];
  for (let i = 0; i <= 14; i++) {
    const u = i / 14;
    if (u > prog) break;
    const x = wL.x + (wK.x - wL.x) * u;
    const y = wL.y + (wK.y - wL.y) * u + Math.sin(u * Math.PI) * 150;
    links.push(<ellipse key={i} cx={x} cy={y} rx={13} ry={7} transform={`rotate(${i % 2 ? 90 : 0} ${x} ${y})`} fill="none" stroke={GOLD} strokeWidth={4} />);
  }
  const HOPS = [0, 1, 2, 3].map((i) => T_PAGAR + i * 0.27);
  const started = HOPS.filter((t) => s >= t).length;
  const landed = HOPS.filter((t) => s >= t + 0.5).length;
  const col = heroCol(s);
  const cam = [{t: T_DICEN, x: 540, y: 1100, zoom: 1.0}, {t: T_PRESTADO, x: 540, y: 1180, zoom: 1.2}, {t: T_INTERESES, x: 540, y: 1160, zoom: 1.15}, {t: T_Y3, x: 540, y: 1000, zoom: 1.1}];
  return (
    <AbsoluteFill>
      <Textura tipo="fibra" base="radial-gradient(circle at 50% 55%, #4a3018 0%, #1c1008 85%)" linea="rgba(255,205,130,0.2)" luz="rgba(255,205,130,0.16)" semilla={30} />
      <Camara paradas={cam}>
        <Brillo x={540} y={1150} r={560} color="rgba(255,200,61,0.24)" />
        <svg width={1080} height={1920} style={{position: 'absolute', inset: 0, overflow: 'visible'}}>
          <Palma x={lendX} y={y0} r={12} k={1.0} piel={PIEL[0]} manga={MANGA[3]} pila={landed} bob={Math.sin(s * 3) * 5} />
          <Palma x={kingX} y={y0} r={-12} k={1.0} piel={PIEL[3]} manga={MANGA[5]} pila={4 - started} bob={Math.sin(s * 3 + 1) * 5} />
          {[[lendX, 12], [kingX, -12]].map(([bx, rr], i) => <rect key={i} x={bx - 60 + (i ? 0 : 0)} y={y0 + 168} width={120} height={22} rx={11} fill={GOLD} stroke={RIM} strokeWidth={3} transform={`rotate(${rr} ${bx} ${y0})`} />)}
          {links}
          <Saco x={sackX} y={sackY} k={1.0} />
          {HOPS.map((t, i) => {
            const p = ro(s, t, t + 0.5);
            if (p <= 0 || p >= 1) return null;
            return <Moneda key={i} x={kingX + (lendX - kingX) * eio(p)} y={y0 - 30 - 230 * 4 * p * (1 - p)} r={26} c={GOLD} sx={Math.cos(s * 16 + i)} />;
          })}
          <g transform={`translate(540 ${1210 + Math.sin(s * 2.4) * 5})`}>
            <Brillo x={0} y={0} r={0} />
            <Moneda x={0} y={0} r={48} c={col} sx={0.78 + 0.22 * Math.cos(s * 2.6)} />
          </g>
        </svg>
        <Ondas x={540} y={1130} t0={T_PRESTADO} color={GOLD} radio={360} />
      </Camara>
      <Chip texto="INTERESES" x={540} y={560} t0={T_INTERESES} t1={T_Y3 - 0.3} color={RED} size={80} />
    </AbsoluteFill>
  );
};

// ================= SITIO 8: la imprenta y el billete que se multiplica (E8) =================
const COPIAS = Array.from({length: 20}).map((_, i) => ({
  t: i < 14 ? (i < 5 ? 37.9 + i * 0.3 : T_SOBRA - 0.3 + (i - 5) * 0.16) : T_SEIMPRIME + (i - 14) * 0.22,
  rot: (i % 2 ? 1 : -1) * (Math.floor(i / 2) % 7 + 1) * 5,
  op: i < 14 ? Math.max(0.1, 0.8 - i * 0.055) : Math.max(0.1, 0.5 - (i - 14) * 0.07),
  dy: -(i % 4) * 8,
}));

const Imprenta: React.FC = () => {
  const {s} = useS();
  const py = interpolate(s, [T_VALE + 0.7, T_PASA + 0.7, T_DINERO1 + 0.3, T_SEIMPRIME - 0.1], [0, -760, -760, 0], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const orig = 1 - eio(ro(s, T_VALE + 0.3, T_PASA));
  const fadeA = 1 - ro(s, T_VALE, T_VALE + 0.9);
  const coin = spr2(s, T_PASA);
  const rot = s * 160;
  const cam = [{t: T_Y3, x: 540, y: 1000, zoom: 1.1}, {t: T_SOBRA, x: 540, y: 1050, zoom: 1.15}, {t: T_PASA, x: 540, y: 1150, zoom: 1.3}, {t: T_DINERO1, x: 540, y: 1100, zoom: 1.3}, {t: T_SEIMPRIME, x: 540, y: 1000, zoom: 1.15}, {t: T_DALE - 0.1, x: 540, y: 900, zoom: 0.85}];
  const col = heroCol(s);
  return (
    <AbsoluteFill>
      <Textura tipo="papel" base="radial-gradient(circle at 50% 55%, #2a3a52 0%, #0e1522 85%)" linea="rgba(160,200,255,0.18)" luz="rgba(120,170,255,0.16)" semilla={41} />
      <Camara paradas={cam}>
        <Brillo x={540} y={1200} r={560} color={s < T_PASA ? 'rgba(180,230,160,0.22)' : 'rgba(255,200,61,0.34)'} />
        <svg width={1080} height={1920} style={{position: 'absolute', inset: 0, overflow: 'visible'}}>
          {COPIAS.map((c, i) => {
            const p = eo(ro(s, c.t, c.t + 0.5));
            if (p <= 0) return null;
            const o = c.op * (i < 14 ? fadeA : 1);
            if (o <= 0.01) return null;
            return <Billete key={i} x={540 + c.rot * 5} y={840 + (1200 + c.dy - 840) * p} r={c.rot * p} op={o} />;
          }).reverse()}
          {orig > 0.01 && <Billete x={540} y={1200} k={1.35 * orig} />}
          {coin > 0.01 && (
            <g transform={`translate(540 1220)`}>
              <circle cx={0} cy={0} r={210 * coin} fill="rgba(255,236,170,0.28)" />
              <Moneda x={0} y={0} r={130 * coin} c={col} sx={0.7 + 0.3 * Math.cos(s * 2.2)} />
              {[0, 1, 2, 3, 4, 5].map((i) => {
                const a = s * 1.2 + (i * Math.PI) / 3;
                return <polygon key={i} points={starPts(14 + 8 * Math.sin(s * 6 + i))} transform={`translate(${Math.cos(a) * 190 * coin} ${Math.sin(a) * 150 * coin})`} fill="#fff" opacity={0.8} />;
              })}
            </g>
          )}
          <g transform={`translate(540 ${700 + py})`}>
            <rect x={-310} y={-200} width={620} height={330} rx={26} fill="#3a4354" stroke="#1b212c" strokeWidth={6} />
            <rect x={-310} y={-200} width={620} height={46} rx={20} fill="#56617a" />
            <path d="M -150 -200 L -110 -290 L 110 -290 L 150 -200 Z" fill="#6a7690" stroke="#1b212c" strokeWidth={5} />
            {[-150, 150].map((cx, i) => (
              <g key={i} transform={`translate(${cx} -30) rotate(${rot * (i ? -1 : 1)})`}>
                <circle r={84} fill="#8b95ab" stroke="#1b212c" strokeWidth={6} />
                {[0, 1, 2, 3, 4, 5].map((a) => <line key={a} x1={0} y1={0} x2={Math.cos((a * Math.PI) / 3) * 70} y2={Math.sin((a * Math.PI) / 3) * 70} stroke="#1b212c" strokeWidth={6} />)}
                <circle r={20} fill="#2c3445" />
              </g>
            ))}
            <rect x={-190} y={96} width={380} height={30} rx={12} fill="#05070b" />
            {[0, 1, 2].map((i) => <circle key={i} cx={-250 + i * 40} cy={-170} r={9} fill={Math.sin(s * 10 + i * 2) > 0 ? '#2fbf71' : '#1f4a35'} />)}
          </g>
        </svg>
        <Ondas x={540} y={1200} t0={T_SOBRA} color="rgba(180,230,160,0.9)" radio={520} />
        <Ondas x={540} y={1220} t0={T_ORO7} color={GOLD} radio={560} />
        <Ondas x={540} y={1220} t0={T_DINERO1} color={GOLD3} radio={480} />
      </Camara>
    </AbsoluteFill>
  );
};

function spr2(s: number, t: number) {
  const k = ro(s, t, t + 0.5);
  return k <= 0 ? 0 : 1 - Math.pow(1 - k, 3) + 0.06 * Math.sin(k * Math.PI);
}

// ---------- grupos (cortes en la palabra, sin Paso donde el plan dice "continúa") ----------
const GrupoA: React.FC = () => { const {s} = useS(); return s < T_LO - 0.02 ? <Mapa /> : <Caravana />; };
const GrupoB: React.FC = () => { const {s} = useS(); return s < T_Y2 - 0.02 ? <Zoco /> : <Balanza />; };
const GrupoC: React.FC = () => { const {s} = useS(); return s < T_DICEN - 0.02 ? <Libro /> : <Prestamo />; };
const GrupoD: React.FC = () => { const {s} = useS(); return s < T_DALE - 0.02 ? <Imprenta /> : <Mercado cierre />; };

