export const SUBS = {arriba: 230, acento: '#FFC83D'};
export const Escena: React.FC = () => {
  const {s} = useS();
  const tint = tono(s, [0, T_AL, T_CAYO - 0.3, T_ORO7 - 0.4, T_DALE, DUR], ['rgba(255,200,61,0.14)', 'rgba(200,160,90,0.22)', 'rgba(255,77,77,0.20)', 'rgba(255,200,61,0.18)', 'rgba(255,200,61,0.14)', 'rgba(255,200,61,0.14)'], 0.8);
  const p1 = <Paso t={T_ANO} tipo="alejar" x={540} y={1000} antes={<Mercado />} despues={<GrupoA />} />;
  const p2 = <Paso t={T_AL} tipo="entrar" x={ENT.x} y={ENT.y} antes={p1} despues={<GrupoB />} />;
  const p3 = <Paso t={T_UN} tipo="barrido" antes={p2} despues={<GrupoC />} />;
  const p4 = <Paso t={T_Y3} tipo="forma" x={540} y={1230} antes={p3} despues={<GrupoD />} />;
  return (
    <AbsoluteFill style={{background: '#000'}}>
      {p4}
      <AbsoluteFill style={{background: tint, mixBlendMode: 'soft-light'}} />
      <Profundidad manchas={3} semilla={7} deriva={0} color="rgba(30,14,4,0.5)" />
      <Destello t0={T_LO - 0.02} fuerza={0.28} />
      <Destello t0={T_Y2 - 0.02} fuerza={0.25} />
      <Destello t0={T_DICEN - 0.02} fuerza={0.25} />
      <Destello t0={T_DALE - 0.02} fuerza={0.3} />
    </AbsoluteFill>
  );
};

